import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
const token=String.fromEnvironment('TMDB_TOKEN');
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF8B5CF6),brightness:Brightness.dark),useMaterial3:true,scaffoldBackgroundColor:const Color(0xFF0B1020),cardTheme:const CardThemeData(color:Color(0xFF151D32),elevation:0,margin:EdgeInsets.zero)),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{List items=[];final saved=<int>{};bool showSaved=false;final search=TextEditingController();String error='';bool busy=true;
@override void initState(){super.initState();loadSaved();load();}
Future<void> loadSaved()async{final p=await SharedPreferences.getInstance();if(mounted)setState(()=>saved.addAll((p.getStringList('savedMovies')??[]).map(int.parse)));}
Future<void> toggleSaved(int id)async{setState(()=>saved.contains(id)?saved.remove(id):saved.add(id));final p=await SharedPreferences.getInstance();await p.setStringList('savedMovies',saved.map((x)=>x.toString()).toList());}
List get visibleItems=>showSaved?items.where((m)=>saved.contains(m['id'])).toList():items;
Future<void> load([String q=''])async{if(token.isEmpty){setState(()=>{error='Configure TMDB_TOKEN with --dart-define.',busy=false});return;}setState(()=>busy=true);try{final path=q.isEmpty?'/movie/popular':'/search/movie';final uri=Uri.https('api.themoviedb.org','3$path',{'query':q,'language':'en-US','page':'1'});final r=await http.get(uri,headers:{'Authorization':'Bearer $token','accept':'application/json'});if(r.statusCode!=200)throw Exception('TMDB error: '+r.statusCode.toString());setState(()=>items=jsonDecode(r.body)['results']??[]);}catch(e){setState(()=>error=e.toString());}finally{setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Malkify Movies'),centerTitle:false,backgroundColor:const Color(0xFF0B1020),actions:[IconButton(tooltip:showSaved?'Show popular movies':'Show saved movies',onPressed:()=>setState(()=>showSaved=!showSaved),icon:Icon(showSaved?Icons.local_movies_outlined:Icons.bookmarks_outlined))]),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:search,onSubmitted:load,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search movies',border:OutlineInputBorder()))),if(error.isNotEmpty)Padding(padding:const EdgeInsets.all(12),child:Text(error,style:const TextStyle(color:Colors.orangeAccent))),if(busy)const CircularProgressIndicator()else Expanded(child:GridView.builder(padding:const EdgeInsets.all(10),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:.58,crossAxisSpacing:10,mainAxisSpacing:10),itemCount:visibleItems.length,itemBuilder:(c,i){final m=visibleItems[i];final id=m['id'] as int;final p=m['poster_path'];return Card(clipBehavior:Clip.antiAlias,child:Column(children:[Expanded(child:p==null?const Icon(Icons.movie):Image.network('https://image.tmdb.org/t/p/w500$p',fit:BoxFit.cover,width:double.infinity)),Text(m['title']??'Untitled',maxLines:2,overflow:TextOverflow.ellipsis),IconButton(onPressed:()=>toggleSaved(id),icon:Icon(saved.contains(id)?Icons.bookmark:Icons.bookmark_border))]));}))]));}}
